INSERT INTO categories (name,created_at,updated_at) SELECT 'Language',datetime('now'),datetime('now') WHERE NOT EXISTS (SELECT 1 FROM categories WHERE name='Language');
INSERT INTO skills (title,description,icon,status,category_id,created_at,updated_at) SELECT 'Conversational Spanish','Everyday Spanish for real conversations.','🗣️','active',(SELECT id FROM categories WHERE name='Language'),datetime('now'),datetime('now') WHERE NOT EXISTS (SELECT 1 FROM skills WHERE title IN ('Conversational Spanish','Spanish'));
